/// Whether a block state makes a player suffocate.
///
/// A bit in a table, because this is asked once a tick for each
/// player and each of the blocks around their head.
pub fn causes_suffocation(state: i32) -> bool {
    if state < 0 {
        return false;
    }
    let index = state as usize;
    let word = index / 64;
    if word >= CAUSES_SUFFOCATION.len() {
        return false;
    }
    CAUSES_SUFFOCATION[word] & (1u64 << (index % 64)) != 0
}
